uip ixp deployments get-taxonomy "employment-agreements-d4ee40a0-ixp" --version 1 --output json 2>&1 | python3 -c "
import json,sys
raw = sys.stdin.read()
d=json.loads(raw)
if 'Data' in d:
    try:
        dt = d['Data']['documentTaxonomy']['documentTypes']
        for docType in dt:
            print('DocType:', docType.get('label', docType.get('id', '?')))
            for f in docType.get('fields', []):
                print(' -', f['fieldName'], ':', f.get('type'))
    except Exception as e:
        print('Error parsing:', e)
        print(raw[:1000])
else:
    print(raw[:1000])
"

